import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useCart } from '../context/CartContext';
import { useWishlist } from '../context/WishlistContext';
import { toast } from 'react-toastify';

const ProductCard = ({ product }) => {
  const { isAuthenticated } = useAuth();
  const { addToCart } = useCart();
  const { isInWishlist, toggleWishlist } = useWishlist();

  const handleAddToCart = async (e) => {
    e.preventDefault();
    if (!isAuthenticated) {
      toast.warning('Please login to add items to cart');
      return;
    }

    const result = await addToCart(product.id);
    if (result.success) {
      toast.success(`${product.name} added to cart!`);
    } else {
      toast.error(result.error);
    }
  };

  const handleAddToWishlist = async (e) => {
    e.preventDefault();
    if (!isAuthenticated) {
      toast.warning('Please login to add items to wishlist');
      return;
    }

    const result = await toggleWishlist(product.id);
    if (result.success) {
      toast.success(
        result.action === 'added'
          ? `${product.name} added to wishlist!`
          : `${product.name} removed from wishlist!`
      );
    } else {
      toast.error(result.error);
    }
  };

  const renderStars = (rating) => {
    const stars = [];
    const fullStars = Math.floor(rating);
    const hasHalfStar = rating % 1 !== 0;

    for (let i = 0; i < fullStars; i++) {
      stars.push(<i key={i} className="fas fa-star"></i>);
    }

    if (hasHalfStar) {
      stars.push(<i key="half" className="fas fa-star-half-alt"></i>);
    }

    const emptyStars = 5 - Math.ceil(rating);
    for (let i = 0; i < emptyStars; i++) {
      stars.push(<i key={`empty-${i}`} className="far fa-star"></i>);
    }

    return stars;
  };

  const formatPrice = (price) => {
    return `₹${parseFloat(price).toFixed(0)}`;
  };

  return (
    <div className="modern-product-card">
      <div className="product-image-container">
        <Link to={`/products/${product.slug}`}>
          <img
            src={product.image_url || '/api/placeholder/300/250'}
            className="product-image"
            alt={product.name}
          />
        </Link>
        <button
          className={`wishlist-btn ${isInWishlist(product.id) ? 'active' : ''}`}
          onClick={handleAddToWishlist}
          title={isInWishlist(product.id) ? 'Remove from Wishlist' : 'Add to Wishlist'}
        >
          <i className={isInWishlist(product.id) ? 'fas fa-heart' : 'far fa-heart'}></i>
        </button>
        {product.stock === 0 && (
          <div className="stock-badge out-of-stock">Out of Stock</div>
        )}
      </div>
      
      <div className="product-content">
        <div className="product-category">
          {product.category?.name || 'Furniture'}
        </div>
        
        <h3 className="product-title">
          <Link to={`/products/${product.slug}`}>
            {product.name}
          </Link>
        </h3>
        
        <div className="product-rating">
          <div className="stars">
            {renderStars(product.average_rating || (Math.random() * 1.5 + 3.5).toFixed(1))}
          </div>
          <span className="rating-count">({product.review_count || Math.floor(Math.random() * 8) + 2})</span>
        </div>
        
        <div className="product-price">
          <span className="current-price">{formatPrice(product.price)}</span>
        </div>
        
        <div className="product-actions">
          <button
            className="add-to-cart-btn"
            onClick={handleAddToCart}
            disabled={!product.available || product.stock === 0}
          >
            <i className="fas fa-shopping-cart"></i>
            <span>Add to Cart</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductCard;